/* NomadMate / OutbackMind service worker.
 *
 * - The list of files to cache comes from /precache-manifest.json (generated by
 *   scripts/build_offline_pack.py). The build script also rewrites the PACK_VERSION line below,
 *   so sw.js changes (byte for byte) whenever any pack file changes. That is what makes browsers
 *   fetch and install the new worker.
 * - Each version has its own cache: om-shell-<PACK_VERSION>. Old om-shell-* caches are removed on activate.
 * - The worker never calls skipWaiting by itself. The page shows "Update available" and sends
 *   SKIP_WAITING when the user taps Reload, so nobody is reloaded in the middle of an emergency.
 * - API calls (anything not on this origin, including https://api.outbackmind.au) are never intercepted
 *   or cached. Requests with ?probe are never intercepted, so the online/offline probe tells the truth.
 * - Kill switch: copy sw-killswitch.js over this file.
 */
const PACK_VERSION = "cd300356512e";
const CACHE_PREFIX = "om-shell-";
const CACHE_NAME = CACHE_PREFIX + PACK_VERSION;
const NETWORK_TIMEOUT_MS = 3000;

self.addEventListener("install", (event) => {
  event.waitUntil((async () => {
    const res = await fetch("/precache-manifest.json", { cache: "no-store" });
    if (!res.ok) throw new Error("precache-manifest.json: HTTP " + res.status);
    const manifest = await res.json();
    if (manifest.version !== PACK_VERSION) {
      // sw.js and the manifest come from different deploys (partial upload). Do not install a mixed pack.
      throw new Error("pack version mismatch: sw " + PACK_VERSION + " vs manifest " + manifest.version);
    }
    const cache = await caches.open(CACHE_NAME);
    const seen = new Set();
    for (const f of manifest.files) {
      if (seen.has(f.url)) continue;
      seen.add(f.url);
      const r = await fetch(new Request(f.url, { cache: "reload" }));
      if (!r.ok) throw new Error(f.url + ": HTTP " + r.status);
      await cache.put(f.url, r);
    }
  })());
});

self.addEventListener("activate", (event) => {
  event.waitUntil((async () => {
    const keys = await caches.keys();
    await Promise.all(keys
      .filter((k) => k.startsWith(CACHE_PREFIX) && k !== CACHE_NAME)
      .map((k) => caches.delete(k)));
    await self.clients.claim();
  })());
});

self.addEventListener("message", (event) => {
  const data = event.data || {};
  if (data.type === "SKIP_WAITING") {
    self.skipWaiting();
  } else if (data.type === "GET_STATUS" && event.ports && event.ports[0]) {
    caches.open(CACHE_NAME).then((c) => c.keys()).then((reqs) => {
      event.ports[0].postMessage({ version: PACK_VERSION, cached: reqs.length });
    }).catch(() => event.ports[0].postMessage({ version: PACK_VERSION, cached: 0 }));
  }
});

function timeout(ms) {
  return new Promise((_, reject) => setTimeout(() => reject(new Error("timeout")), ms));
}

async function networkFirst(request, fallbackUrl) {
  try {
    const fresh = await Promise.race([
      fetch(request.url, { cache: "no-cache", credentials: "same-origin" }),
      timeout(NETWORK_TIMEOUT_MS),
    ]);
    if (fresh && fresh.ok) return fresh;
    // Server answered with an error (for example 404 after a bad deploy): prefer the cached copy if we have one.
    const cached = await caches.match(request, { ignoreSearch: true, cacheName: CACHE_NAME });
    return cached || fresh;
  } catch (err) {
    const cached = await caches.match(request, { ignoreSearch: true, cacheName: CACHE_NAME });
    if (cached) return cached;
    if (fallbackUrl) {
      const fb = await caches.match(fallbackUrl, { cacheName: CACHE_NAME });
      if (fb) return fb;
    }
    return new Response("Offline", { status: 503, statusText: "Offline", headers: { "Content-Type": "text/plain" } });
  }
}

async function cacheFirst(request) {
  const cached = await caches.match(request, { ignoreSearch: true, cacheName: CACHE_NAME });
  if (cached) return cached;
  try {
    return await fetch(request);
  } catch (err) {
    return new Response("Offline", { status: 503, statusText: "Offline" });
  }
}

self.addEventListener("fetch", (event) => {
  const request = event.request;
  if (request.method !== "GET") return;
  const url = new URL(request.url);
  // Never touch other origins (the API lives on api.outbackmind.au) or the probe.
  if (url.origin !== self.location.origin) return;
  if (url.searchParams.has("probe")) return;
  if (url.pathname === "/sw.js" || url.pathname === "/sw-killswitch.js" || url.pathname === "/precache-manifest.json") return;

  if (request.mode === "navigate") {
    event.respondWith(networkFirst(request, "/offline.html"));
    return;
  }

  if (url.pathname.startsWith("/icons/")) {
    event.respondWith(cacheFirst(request));
    return;
  }

  // Scripts, styles, data, config, manifest: network-first (3 s) so online visitors always get the
  // current files, falling back to the cached pack when offline or on a very slow connection.
  event.respondWith(networkFirst(request));
});
